-- ------------------------------------------------------------------------
-- 0048_record_audit.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Database-enforced audit trail. The client-side audit_log records user actions,
-- but a defensible Part 11 / QMS audit trail must be created by the database so
-- it cannot be bypassed or altered. record_audit captures every INSERT / UPDATE
-- / DELETE on the quality-record tables, with the acting user, timestamp and the
-- before/after row. It is written only by SECURITY DEFINER triggers, read only
-- by admins, and never updatable/deletable by users.
-- ===========================================================================

create table if not exists public.record_audit (
  id          bigint generated always as identity primary key,
  table_name  text not null,
  op          text not null,           -- INSERT | UPDATE | DELETE
  record_key  text,                    -- ucn / uid / call_number / id
  actor       uuid,
  actor_email text,
  changed_at  timestamptz not null default now(),
  old_data    jsonb,
  new_data    jsonb
);
create index if not exists record_audit_at_idx  on public.record_audit (changed_at desc);
create index if not exists record_audit_tbl_idx on public.record_audit (table_name, changed_at desc);
create index if not exists record_audit_key_idx on public.record_audit (record_key);

create or replace function public.record_audit_fn()
returns trigger language plpgsql security definer set search_path = public as $$
declare j jsonb;
begin
  if tg_op = 'DELETE' then j := to_jsonb(old); else j := to_jsonb(new); end if;
  insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
  values (
    tg_table_name, tg_op,
    coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
    auth.uid(), auth.email(),
    case when tg_op <> 'INSERT' then to_jsonb(old) else null end,
    case when tg_op <> 'DELETE' then to_jsonb(new) else null end
  );
  return case when tg_op = 'DELETE' then old else new end;
end $$;

alter table public.record_audit enable row level security;
grant select on public.record_audit to authenticated;   -- read only; no insert/update/delete grant
drop policy if exists record_audit_read on public.record_audit;
create policy record_audit_read on public.record_audit for select
  using (public.is_admin() or public.has_perm('audit.view'));

-- Attach to the quality-record tables that exist.
do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback',
    'call_requests', 'pending_registrations'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists record_audit_t on public.%I', t);
      execute format('create trigger record_audit_t after insert or update or delete on public.%I for each row execute function public.record_audit_fn()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0049_record_retention_guard.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Record-retention guard. Quality records must be retained, not deleted — an
-- auditor expects that a service record, visit report or spare request cannot
-- be removed. Hard DELETE on these append-only quality tables is blocked; the
-- app uses status / cancel / drop workflows instead, which are captured by the
-- audit trail. (Configuration/operational tables are not covered here.)
-- ===========================================================================

create or replace function public.block_hard_delete()
returns trigger language plpgsql as $$
begin
  -- Application deletion (the authenticated role, via PostgREST) is blocked for
  -- retention. Controlled deletion by a DBA/superuser (e.g. an approved archival
  -- procedure in the SQL editor) is permitted and is still captured by the
  -- database audit trail.
  if current_user = 'authenticated' then
    raise exception
      'RECORD RETENTION: % records cannot be deleted (row %). Use the defined status / cancel / drop workflow.',
      tg_table_name,
      coalesce(to_jsonb(old)->>'ucn', to_jsonb(old)->>'uid', to_jsonb(old)->>'call_number', to_jsonb(old)->>'id');
  end if;
  return old;
end $$;

do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists no_hard_delete on public.%I', t);
      execute format('create trigger no_hard_delete before delete on public.%I for each row execute function public.block_hard_delete()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0103_record_audit_not_bulk.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE AUDIT TRAIL RECORDS WHAT PEOPLE DO, NOT WHAT A LOAD LOADED.
--
-- `record_audit` (0048) kept a row, with the whole record before and after, for
-- every INSERT / UPDATE / DELETE on the quality tables. That is right for a
-- person changing a record and wrong for a bulk load: migrating the sheet era
-- wrote tens of thousands of audit rows that say nothing a migration report
-- does not say better, and they are the reason the table grew as it did.
--
-- An audit trail exists to answer "who changed this record, and to what". A
-- one-time load is not that question; it is answered by the migration's own
-- verification (the DM checks in the validation package: row counts reconciled,
-- fields sampled, identifiers checked).
--
-- SO A BULK WRITE IS STILL RECORDED — AS ONE EVENT, NOT TEN THOUSAND. The row
-- says who loaded, into which table, how many rows and when. The load remains
-- attributable, which is what Part 11 asks of it; what goes is the per-record
-- duplicate of data that is already in the table it was loaded into.
--
-- HOW THE LINE IS DRAWN. A statement-level trigger with transition tables can
-- count the rows one statement touched, which a row-level trigger cannot. The
-- threshold sits between the largest write a PERSON makes in one statement and
-- the smallest a LOADER makes:
--
--     bulk re-allotment   100 rows per statement  (reallocateCalls, src/lib/supabase.ts)
--     bulk upload         300 or 500 per statement (uploadRows, same file)
--
-- 150 sits between them, and if either chunk size changes this number wants
-- revisiting. But the margin is wider than those numbers suggest, and it is
-- worth knowing why:
--
--   THE BULK USER ACTIONS GO THROUGH THE `calls` VIEW, and 0040's INSTEAD OF
--   triggers write it ROW BY ROW into the typed table. So at the table — which
--   is where this trigger sits — a hundred-call re-allotment arrives as a
--   hundred single-row statements and is audited in full, whatever the
--   threshold. The loaders write to `field_calls`, `spare_requests`,
--   `spare_consumption` and the rest DIRECTLY, in one statement per batch.
--
-- Verified on Postgres, all three: 500 rows loaded into field_calls -> one BULK
-- INSERT row; a re-allotment through the view -> a row each, with before and
-- after intact; a re-load UPDATING 500 rows -> one BULK UPDATE row.
--
-- Everything else is unchanged: written only by a SECURITY DEFINER trigger,
-- readable only by an administrator or `audit.view`, and still not writable or
-- alterable by anyone.
-- ===========================================================================

create or replace function public.record_audit_fn()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  n     bigint;
  bulk  boolean;
begin
  -- How many rows this ONE statement touched.
  if tg_op = 'DELETE' then
    select count(*) into n from old_rows;
  else
    select count(*) into n from new_rows;
  end if;
  if n = 0 then return null; end if;

  bulk := n > 150;

  if bulk then
    -- One row for the whole statement: who, what table, how many, when.
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    values (tg_table_name, 'BULK ' || tg_op, null, auth.uid(), auth.email(), null,
            jsonb_build_object('rows', n,
                               'note', 'Bulk write — recorded as one event. The records are in ' || tg_table_name || '.'));
    return null;
  end if;

  -- Otherwise exactly what 0048 did, a row at a time, from the transition
  -- tables rather than from OLD / NEW.
  if tg_op = 'INSERT' then
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
           auth.uid(), auth.email(), null, j
      from (select to_jsonb(r) as j from new_rows r) x;
  elsif tg_op = 'DELETE' then
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
           auth.uid(), auth.email(), j, null
      from (select to_jsonb(r) as j from old_rows r) x;
  else
    -- UPDATE: the before and after of the same record, paired on the key the
    -- audit is written under. A quality table without one of these keys cannot
    -- be paired, so both images are still written and the key reads null.
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(nj->>'ucn', nj->>'uid', nj->>'line_uid', nj->>'call_number', nj->>'id'),
           auth.uid(), auth.email(), oj, nj
      from (
        select to_jsonb(nr) as nj,
               (select to_jsonb(orow) from old_rows orow
                 where coalesce(to_jsonb(orow)->>'ucn', to_jsonb(orow)->>'uid', to_jsonb(orow)->>'line_uid',
                                to_jsonb(orow)->>'call_number', to_jsonb(orow)->>'id')
                       is not distinct from
                       coalesce(to_jsonb(nr)->>'ucn', to_jsonb(nr)->>'uid', to_jsonb(nr)->>'line_uid',
                                to_jsonb(nr)->>'call_number', to_jsonb(nr)->>'id')
                 limit 1) as oj
          from new_rows nr
      ) x;
  end if;
  return null;
end $$;

-- Re-attach: one trigger PER OPERATION now, because a statement trigger names
-- the transition table it needs and INSERT has no OLD, DELETE no NEW.
do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback',
    'call_requests', 'pending_registrations'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists record_audit_t on public.%I', t);
      execute format('drop trigger if exists record_audit_i on public.%I', t);
      execute format('drop trigger if exists record_audit_u on public.%I', t);
      execute format('drop trigger if exists record_audit_d on public.%I', t);
      execute format('create trigger record_audit_i after insert on public.%I '
                     'referencing new table as new_rows for each statement '
                     'execute function public.record_audit_fn()', t);
      execute format('create trigger record_audit_u after update on public.%I '
                     'referencing old table as old_rows new table as new_rows for each statement '
                     'execute function public.record_audit_fn()', t);
      execute format('create trigger record_audit_d after delete on public.%I '
                     'referencing old table as old_rows for each statement '
                     'execute function public.record_audit_fn()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0112_stop_record_audit.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- STOP WRITING TO record_audit. THE AUDIT LOG IS ENOUGH.
--
-- 0048 added a database-enforced trail — a before/after image of every row
-- written to the ten quality-record tables — because a defensible 21 CFR
-- Part 11 trail has to be created by the database rather than the client.
-- Part 11 is FDA's; this operation is regulated by CDSCO under the Medical
-- Devices Rules, 2017, which asks for records to be controlled and retrievable
-- and does not prescribe that second trail. The user's decision, 2026-09-05:
-- `audit_log` is the trail.
--
-- WHAT THIS DOES AND DOES NOT DO.
--   • The ten triggers are dropped, so nothing writes to `record_audit` again.
--   • The TABLE STAYS, with whatever it already holds. It is a quality record
--     of what happened while it was running, and 0049 forbids deleting those.
--     Dropping it is a separate decision and a separate script.
--   • `record_audit_fn()` stays too, unattached. Re-attaching is then one
--     `create trigger`, not a migration to write again.
--
-- IT IS A REDUCTION, AND THE PACKAGE SAYS SO. `audit_log` is written by the
-- CLIENT: it can be bypassed by a direct API call and it is purged on the
-- retention window. `record_audit` could not be bypassed and was not purged.
-- The validation package is updated in the same change rather than left
-- claiming a control that has been switched off.
-- ===========================================================================

do $stop$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports', 'call_requests',
    'pending_registrations', 'feedback', 'spare_requests', 'spare_request_lines',
    'spare_consumption'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('drop trigger if exists record_audit_i on public.%I', t);
      execute format('drop trigger if exists record_audit_u on public.%I', t);
      execute format('drop trigger if exists record_audit_d on public.%I', t);
    end if;
  end loop;
end $stop$;

-- Nothing writes it now, so nothing should think it can. The read policy is
-- left alone: what is already recorded stays readable by an administrator.
comment on table public.record_audit is
  'HISTORICAL. Written by triggers from 0048 until 0112 stopped them (2026-09-05) — audit_log is the trail now. Retained, not maintained: everything here happened while it was running.';

-- ------------------------------------------------------------------------
-- 0166_ffr_retention_guard.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0166 — the Field Failure Register keeps its records.
--
-- Filed in `data_integrity` rather than beside the table (0165), because
-- block_hard_delete() is defined in THIS module and this module runs AFTER
-- daily_review in ALL_ORDER. Putting the trigger next to the table made a fresh
-- apply fail on a function that did not exist yet, which check:replay caught.
--
-- GUARDED on the table's presence, the way the replay tails are: running
-- data_integrity alone against a database that has not had daily_review yet
-- must skip this, not fail.
--
-- Deletion is already impossible for the application without this: 0165 grants
-- no DELETE policy, so a delete as `authenticated` matches no rows and silently
-- affects none. This is the second lock — it turns that silence into a refusal
-- the day somebody adds a delete policy.
-- ===========================================================================
do $$
begin
  if to_regclass('public.field_failure_reports') is not null
     and to_regprocedure('public.block_hard_delete()') is not null then
    execute 'drop trigger if exists no_hard_delete on public.field_failure_reports';
    execute 'create trigger no_hard_delete before delete on public.field_failure_reports '
         || 'for each row execute function public.block_hard_delete()';
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0174_ffr_history.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0174 — EVERY CHANGE TO A FIELD FAILURE REPORT IS RECORDED.
--
-- The user, 2026-09-12: "And where is the FFR update? I need to be able to
-- capture everytime it is updated - For log keeping."
--
-- The FFR is reviewed WEEKLY and edited each time — the observation grows, the
-- problem status is written, a CAPA is opened and later closed, the report is
-- closed or cancelled. Today the register holds only the CURRENT state, so the
-- question a weekly cycle actually asks — what changed since last week, and who
-- changed it — has no answer anywhere.
--
-- IN THE DATABASE, NOT THE CLIENT, and that is the whole point of doing it here
-- rather than adding another logAudit() call. The application's audit trail is
-- client-written, so it records what the screen chose to tell it and nothing
-- about an edit made straight through the API (this is stated plainly in the
-- validation package, FRS-021). A change history for a quality record that a
-- caller can decline to write is not a change history. This trigger sees every
-- UPDATE by every path.
--
-- ONE ROW PER UPDATE, not per field. An edit is one act by one person at one
-- moment; splitting it across six rows makes "what did she change on Tuesday"
-- a reassembly job. The fields are held in `changes` as
-- {"column": {"from": …, "to": …}} — only the columns that actually differ.
--
-- AND AN UPDATE THAT CHANGES NOTHING WRITES NOTHING. Re-saving a form without
-- touching it is not an event, and a log full of them is a log nobody reads.
--
-- APPEND-ONLY. No update policy and no delete policy exist, so the history
-- cannot be edited or tidied by anyone through the API — the record of what a
-- record used to say is itself a quality record (0049's rule).
-- ===========================================================================

create table if not exists public.ffr_history (
  id            bigserial primary key,
  ffr_id        bigint      not null references public.field_failure_reports (id) on delete cascade,
  -- The NUMBER as well as the id: the id is an implementation detail, and the
  -- number is what a person reading the log recognises.
  ffr_no        text        not null default '',
  changed_at    timestamptz not null default now(),
  changed_by    uuid        references auth.users (id),
  changed_by_name text      not null default '',
  -- 'update' today; 'create' marks the row the report was raised with, so the
  -- history starts at the beginning rather than at the first edit.
  action        text        not null default 'update',
  changes       jsonb       not null default '{}'::jsonb
);

create index if not exists ffr_history_ffr_idx  on public.ffr_history (ffr_id, changed_at desc);
create index if not exists ffr_history_when_idx on public.ffr_history (changed_at desc);

alter table public.ffr_history enable row level security;

-- WHOEVER MAY READ THE REGISTER MAY READ ITS HISTORY. Anything narrower would
-- mean a report somebody can see whose changes they cannot — which is the
-- question the log exists to answer.
drop policy if exists ffrh_read on public.ffr_history;
create policy ffrh_read on public.ffr_history for select to authenticated
  using ((select public.has_perm('ffr.manage')) or (select public.is_admin()));

-- NO insert policy: the trigger is SECURITY DEFINER and writes as the owner, so
-- a client cannot forge an entry even with the grant below.
-- NO update or delete policy: append-only, by omission rather than by promise.
grant select on public.ffr_history to authenticated;

-- ---------------------------------------------------------------------------
-- WHAT CHANGED. Columns compared as text, which is what the log displays and
-- what makes '2026-09-12' and a date the same thing to a reader.
--
-- The bookkeeping columns are SKIPPED: updated_at moves on every write, and a
-- log whose every entry says "updated_at changed" buries the one that says the
-- CAPA was closed.
-- ---------------------------------------------------------------------------
create or replace function public.ffr_history_write()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_old  jsonb := to_jsonb(old);
  v_new  jsonb := to_jsonb(new);
  v_diff jsonb := '{}'::jsonb;
  k      text;
  v_name text;
  -- Not worth an entry: set by the database on every write, or never changed.
  skip   text[] := array['updated_at', 'id', 'ffr_no', 'raised_by', 'created_at'];
begin
  for k in select jsonb_object_keys(v_new) loop
    if k = any (skip) then continue; end if;
    if v_new -> k is distinct from v_old -> k then
      v_diff := v_diff || jsonb_build_object(k, jsonb_build_object('from', v_old -> k, 'to', v_new -> k));
    end if;
  end loop;

  -- Nothing actually changed: re-saving a form untouched is not an event.
  if v_diff = '{}'::jsonb then return null; end if;

  select coalesce(nullif(btrim(d.name), ''), nullif(btrim(p.full_name), ''), p.email)
    into v_name
    from public.profiles p
    left join public.user_directory d
      on lower(btrim(d.email)) = lower(btrim(p.email))
      or lower(btrim(d.gmail)) = lower(btrim(p.email))
   where p.id = auth.uid();

  insert into public.ffr_history (ffr_id, ffr_no, changed_by, changed_by_name, action, changes)
  values (new.id, coalesce(new.ffr_no, ''), auth.uid(), coalesce(v_name, ''), 'update', v_diff);

  return null;
end $$;

drop trigger if exists zz_ffr_history on public.field_failure_reports;
create trigger zz_ffr_history after update on public.field_failure_reports
  for each row execute function public.ffr_history_write();

-- ---------------------------------------------------------------------------
-- THE FIRST ENTRY. A history that begins at the first EDIT cannot say when the
-- report came into being or who raised it, which is the one entry every other
-- one is read against.
-- ---------------------------------------------------------------------------
create or replace function public.ffr_history_created()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.ffr_history (ffr_id, ffr_no, changed_by, changed_by_name, action, changes)
  values (new.id, coalesce(new.ffr_no, ''), new.raised_by, coalesce(new.raised_by_name, ''), 'create',
          jsonb_build_object('ffr_date', jsonb_build_object('from', null, 'to', new.ffr_date),
                             'ucn',      jsonb_build_object('from', null, 'to', new.ucn)));
  return null;
end $$;

drop trigger if exists zz_ffr_history_created on public.field_failure_reports;
create trigger zz_ffr_history_created after insert on public.field_failure_reports
  for each row execute function public.ffr_history_created();

-- ---------------------------------------------------------------------------
-- THE REPORTS THAT ALREADY EXIST get their 'create' entry, so every report on
-- the register has a history that starts somewhere. Idempotent: a report that
-- already has one is skipped, so this file can be re-run.
-- ---------------------------------------------------------------------------
insert into public.ffr_history (ffr_id, ffr_no, changed_at, changed_by, changed_by_name, action, changes)
select f.id, coalesce(f.ffr_no, ''),
       coalesce(f.ffr_date::timestamptz, f.updated_at, now()),
       f.raised_by, coalesce(f.raised_by_name, ''), 'create',
       jsonb_build_object('ffr_date', jsonb_build_object('from', null, 'to', f.ffr_date),
                          'ucn',      jsonb_build_object('from', null, 'to', f.ucn))
  from public.field_failure_reports f
 where not exists (select 1 from public.ffr_history h where h.ffr_id = f.id and h.action = 'create');

-- ---------------------------------------------------------------------------
-- THE RETENTION PURGE MUST NOT REACH IT. 0166 blocks deletion of a field
-- failure report; its history is the same record seen over time, and a log that
-- can be purged while the record it describes cannot is a gap with no reason
-- for being there.
-- ---------------------------------------------------------------------------
do $$
begin
  if to_regprocedure('public.block_hard_delete()') is not null then
    execute 'drop trigger if exists zz_no_delete on public.ffr_history';
    execute 'create trigger zz_no_delete before delete on public.ffr_history
               for each row execute function public.block_hard_delete()';
  else
    raise notice 'block_hard_delete() is not present yet — ffr_history is unprotected until data_integrity.sql runs.';
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0177_ffr_history_view_right.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0177 — THE UPDATE LOG FOLLOWS THE REGISTER.
--
-- 0176 made reading the Field Failure Register its own right (`ffr.view`).
-- 0174 gated the change log on `ffr.manage`, which would now leave somebody
-- able to read a report but NOT what changed on it — and the log exists to be
-- read alongside the record it describes.
--
-- A FILE OF ITS OWN, and not a tidiness choice: `ffrh_read` is created by 0174
-- in the `data_integrity` module, while `ffr_read` belongs to `daily_review`.
-- One migration redefining both would sit in one module and be reverted by a
-- replay of the other — `check:bundles` refuses exactly that, and caught it
-- here before it shipped.
-- ===========================================================================

drop policy if exists ffrh_read on public.ffr_history;
create policy ffrh_read on public.ffr_history for select to authenticated
  using (
        (select public.has_perm('ffr.view'))
     or (select public.has_perm('ffr.manage'))
     or (select public.is_admin())
  );

-- ------------------------------------------------------------------------
-- 0186_feedback_key.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0186 — FEEDBACK IS KEYED ON THE CALL.
--
-- The user, 2026-09-13: "Feedback has KEY - Simply use it." They are right, and
-- the export proves it: v2Feedback - Merge has 24,749 rows and 24,748 DISTINCT
-- UC Numbers with ZERO repeats. One feedback per call is what the register has
-- always been; nothing was enforcing it.
--
-- Until now the upload declared no conflict target, so its own note admitted
-- "No natural key, so a re-run ADDS rows" — load the export twice and the
-- register holds it twice, with nothing to say which is current.
--
-- `ucn_key` is GENERATED and STORED so the index is a plain btree: an
-- expression index is not a target PostgREST can infer, which `check:upserts`
-- refuses for that reason.
--
-- AND THE INDEX IS NOT PARTIAL, which the first version of this file got wrong.
-- `where ucn_key <> ''` looks like the careful thing — key the rows that have a
-- UCN, leave the rest alone — but a PARTIAL index is not inferable either, and
-- check:upserts said so:
--
--     NO INFERABLE UNIQUE INDEX for (ucn_key) on feedback
--
-- So a blank UCN keys off ITS OWN ROW instead: `row-<id>`, which is unique by
-- construction and can never collide with another. The index covers every row,
-- PostgREST can infer it, and no feedback is deleted to tidy an index — which
-- is what a total index over a plain lower(ucn) would have forced, since every
-- blank would have collided with every other blank.
--
-- The importer requires the UCN anyway, so no blank row arrives that way. This
-- is about the ones already there.
-- ===========================================================================

alter table public.feedback
  add column if not exists ucn_key text generated always as
    (coalesce(nullif(lower(btrim(coalesce(ucn, ''))), ''), 'row-' || id)) stored;

-- Existing duplicates first, or the index cannot be built. The LATEST row wins:
-- a second feedback for one call is a correction of the first, which is the
-- same rule the other registers use. Blank-UCN rows are NOT touched — they are
-- not duplicates of each other, and deleting somebody's feedback because it
-- lacks a call number would be destroying a record to tidy an index.
delete from public.feedback a
 using public.feedback b
 where lower(btrim(coalesce(a.ucn, ''))) = lower(btrim(coalesce(b.ucn, '')))
   and lower(btrim(coalesce(a.ucn, ''))) <> ''
   and a.id < b.id;

create unique index if not exists feedback_ucn_key_uniq on public.feedback (ucn_key);

comment on index public.feedback_ucn_key_uniq is
  'One feedback per call. The v2Feedback export has 24,748 distinct UC Numbers in 24,749 rows and no repeats — the key was always there, nothing was using it, and a second load duplicated the register. A row with no UCN keys off its own id, so it is unique rather than colliding with every other blank.';

-- ------------------------------------------------------------------------
-- 0188_feedback_key_repair.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0188 — 0186 CANNOT FIX A PROJECT THAT RAN ITS FIRST VERSION. THIS CAN.
--
-- Reported from use, 2026-09-14, AFTER running the corrected bundle:
--
--     Customer Feedback - there is no unique or exclusion constraint matching
--     the ON CONFLICT specification (row ~1) ... (0 written before it stopped.)
--
-- The bundle ran. It reported success. It changed NOTHING, and that is the
-- whole fault:
--
--   * `alter table ... ADD COLUMN IF NOT EXISTS ucn_key ... generated always as
--     (<new expression>)` is a no-op when the column exists. The GENERATION
--     EXPRESSION is not compared — the old one survives, silently.
--   * `CREATE UNIQUE INDEX IF NOT EXISTS feedback_ucn_key_uniq ...` is a no-op
--     when an index of that NAME exists. Its DEFINITION is not compared — the
--     old PARTIAL index survives, silently.
--
-- So a project that had run the first version of 0186 (the one with
-- `where ucn_key <> ''`) keeps the partial index for ever, and PostgREST cannot
-- infer a partial index as an ON CONFLICT target. Every subsequent run of the
-- corrected file confirms it is already correct.
--
-- PROVED, not reasoned: a throwaway Postgres was built with every migration
-- except 0186, the FIRST version of 0186 applied by hand, and then the current
-- `data_integrity.sql` run over it. The bundle emitted no error and the index
-- was still `... USING btree (ucn_key) WHERE (ucn_key <> ''::text)`, with the
-- column still generated as `lower(btrim(COALESCE(ucn, ''::text)))`.
--
-- THE LESSON, and it is why this is a new file rather than an edit to 0186:
-- `IF NOT EXISTS` guards a NAME, never a DEFINITION. It makes a migration
-- re-runnable; it does NOT make it corrective. Anything that CHANGES the shape
-- of an object someone may already have must inspect what is there and replace
-- it. 0185 got this right by accident — it named the new index differently
-- (`..._machine_key_uniq`) and dropped the old one by its own name. 0186 reused
-- both names, which is the one case in this tree where the trap bites.
--
-- Written so it is safe on EVERY state: never applied, applied at the first
-- version, applied at the corrected version. It rebuilds only what is wrong.
-- ===========================================================================

do $$
declare
  v_expr text;
  v_idx  record;
  v_n    int;
begin
  if to_regclass('public.feedback') is null then
    raise notice '0188: public.feedback is absent -- nothing to repair';
    return;
  end if;

  -- 1. THE COLUMN. Its expression decides, not its existence. The corrected
  --    expression falls back to `row-<id>` for a blank UCN; the first version
  --    yielded a bare '' that every other blank row collided with, which is
  --    what forced the partial index in the first place.
  select pg_get_expr(d.adbin, d.adrelid) into v_expr
    from pg_attrdef d
    join pg_attribute a on a.attrelid = d.adrelid and a.attnum = d.adnum
   where d.adrelid = 'public.feedback'::regclass and a.attname = 'ucn_key';

  if v_expr is not null and v_expr not like '%row-%' then
    -- Dropping a GENERATED STORED column loses nothing: every value is derived
    -- from `ucn` and `id`, both still here. The drop cascades to the indexes
    -- over it, which takes the stale partial index with it.
    raise notice '0188: feedback.ucn_key carries the superseded expression -- rebuilding it';
    execute 'alter table public.feedback drop column ucn_key';
    v_expr := null;
  end if;

  if v_expr is null then
    execute $g$alter table public.feedback
      add column ucn_key text generated always as
        (coalesce(nullif(lower(btrim(coalesce(ucn, ''))), ''), 'row-' || id)) stored$g$;
  end if;

  -- 2. THE INDEX. Found by SHAPE, not by name -- a project that hand-built one
  --    under another name is in exactly the same trouble, and PostgREST looks
  --    at shape too. A partial index (`indpred`) and an expression index
  --    (`indexprs`) are both uninferable as an ON CONFLICT target.
  for v_idx in
    select i.indexrelid::regclass::text as name
      from pg_index i
     where i.indrelid = 'public.feedback'::regclass
       and i.indisunique
       and (i.indpred is not null or i.indexprs is not null)
       and pg_get_indexdef(i.indexrelid) ilike '%ucn_key%'
  loop
    raise notice '0188: dropping % -- partial or expression, so not an inferable upsert target', v_idx.name;
    execute format('drop index if exists public.%I', v_idx.name);
  end loop;

  -- 3. Duplicates, or the total index cannot be built. The LATEST row wins: a
  --    second feedback for one call is a correction of the first. Blank-UCN
  --    rows are untouched -- they key off their own id now, so they are unique
  --    by construction and nobody's feedback is deleted to tidy an index.
  delete from public.feedback a
   using public.feedback b
   where lower(btrim(coalesce(a.ucn, ''))) = lower(btrim(coalesce(b.ucn, '')))
     and lower(btrim(coalesce(a.ucn, ''))) <> ''
     and a.id < b.id;
  get diagnostics v_n = row_count;
  if v_n > 0 then
    raise notice '0188: % duplicate feedback row(s) superseded by the later entry', v_n;
  end if;

  if not exists (
    select 1 from pg_index i
     where i.indrelid = 'public.feedback'::regclass
       and i.indisunique and i.indpred is null and i.indexprs is null
       and pg_get_indexdef(i.indexrelid) ilike '%(ucn_key)%')
  then
    execute 'create unique index feedback_ucn_key_uniq on public.feedback (ucn_key)';
    raise notice '0188: feedback_ucn_key_uniq created -- one feedback per call';
  else
    raise notice '0188: the key is already correct -- nothing changed';
  end if;
end $$;

comment on index public.feedback_ucn_key_uniq is
  'One feedback per call. The v2Feedback export has 24,748 distinct UC Numbers in 24,749 rows and no repeats — the key was always there, nothing was using it, and a second load duplicated the register. A row with no UCN keys off its own id, so it is unique rather than colliding with every other blank. Rebuilt by 0188 where 0186''s first version had left a PARTIAL index that no later run could replace.';

-- ------------------------------------------------------------------------
-- 0189_feedback_update_policy.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0189 — A KEY WITHOUT AN UPDATE POLICY IS AN UPSERT THAT CANNOT UPSERT.
--
-- Reported from use, 2026-09-14, loading the feedback export once the key was
-- finally in place:
--
--     Your role does not have permission for this action. (row ~24093)
--     (24092 written before it stopped.)
--
-- 24,092 rows went in, so the key works. Then one row COLLIDED, the upsert
-- turned from an INSERT into an UPDATE, and `public.feedback` has no UPDATE
-- policy at all — 0001 gave it a read and an insert, 0008 narrowed those two to
-- rights, and nobody ever added the third because nothing ever updated a
-- feedback row.
--
-- THAT IS THE SHAPE OF THE FAULT, and it is worth stating plainly: giving a
-- table a conflict target CHANGES WHICH POLICY THE IMPORTER NEEDS. Before 0186
-- the feedback upload declared no key, so every row was an insert and the
-- missing UPDATE policy could never matter. The moment the key existed, the
-- first colliding row needed a permission nobody held — and it fails at the
-- ONE MOMENT an upsert is meant to earn its keep, which is the re-load.
--
-- `check:upserts` did not catch it because it checks the INDEX: it answers "can
-- PostgREST infer a conflict target?" and not "may the caller write the row it
-- infers?". It now asks both.
--
-- WHO MAY CORRECT A FEEDBACK: exactly whoever may file one. The audience is
-- copied from `fb_write` VERBATIM rather than widened — this grants no new
-- person any new reach, it lets the people who could already add a feedback
-- for a call replace the one that is there. That is the rule 0186 wrote down
-- and this is what makes it true:
--
--     "a second feedback for one call is a correction of the first, which is
--      the same rule the other registers use"
--
-- USING and WITH CHECK are BOTH given, and deliberately not left to default:
-- an UPDATE policy with no USING lets nobody update anything, which would have
-- fixed nothing while looking like a fix.
-- ===========================================================================

drop policy if exists fb_update on public.feedback;
create policy fb_update on public.feedback for update
  using       (public.has_perm('calls.report') or public.has_perm('feedback.view'))
  with check  (public.has_perm('calls.report') or public.has_perm('feedback.view'));

comment on table public.feedback is
  'Customer feedback, one row per call (ucn_key, 0186/0188). A second feedback for the same call REPLACES the first — that is what the key is for — so whoever may file one may correct one (fb_update, 0189). Without that policy the upload inserted until the first collision and then stopped, which is exactly when an upsert is supposed to work.';

-- ------------------------------------------------------------------------
-- 0190_feedback_dates_and_origin.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0190 — CUSTOMER FEEDBACK GETS ITS OWN DATE, AND SAYS WHERE IT CAME FROM.
--
-- Reported from use, 2026-09-14, after loading the v2Feedback export:
--
--    "I think the Date is taken as 14Sep2026 for all Uploads , I wanted the
--     Actual Dates as per the CSV not the Upload date -- It creates a
--     Complaint issue"
--
-- Right, and it is worse than a display fault. The register's Date column read
-- `created_at`, which is when the ROW was written here — so twenty-four
-- thousand feedbacks collected over two years all read as one afternoon in
-- September 2026. On a complaint record that is not a cosmetic problem: the
-- date a customer complained is part of the record.
--
-- THE REAL DATES WERE NEVER LOST, and that is what makes this fixable without
-- asking anybody to load the file again. The importer is declared
-- `extraInto: 'answers'`, which keeps every unmapped column on the row UNDER
-- ITS ORIGINAL SPREADSHEET HEADING. Measured against the user's own file
-- (v2Feedback - Merge.csv, 24,749 rows):
--
--    "Visit Entry Date"    24,748 filled   e.g. 02-Jan-2025 11:18:59
--    "Visit Date & Time"   24,748 filled   e.g. 01 January 2025
--
-- The first is when the feedback was taken; the second is the visit it is
-- about. The second was already mapped to `visit_at`. The first had no column,
-- so it sat in `answers` — present, and invisible.
--
-- SO THIS BACKFILLS RATHER THAN REQUIRING A RE-UPLOAD. Every already-loaded row
-- carries its own date in `answers`, and this reads it back out.
--
-- `entry_at` DEFAULTS TO now() so a feedback recorded IN THIS SYSTEM has a
-- meaningful date too: the column means "when this feedback was taken", which
-- for a new one is now and for a migrated one is what the file said. A column
-- that is only correct for imported rows would just move the problem.
--
-- AND `imported_from`, which answers the other half of the same question
-- ("Can I segregate the Uploaded ones and the Ones that were entered in the new
-- CRM?"). Same shape as the Field Failure Register's (0179): the file a row
-- came in from, empty meaning this system raised it. A figure drawn from both
-- has to be able to report the split — the validation package requires it
-- (URS-037) and until now this register could not.
--
-- THE PARSING IS GUARDED. `to_timestamp('rubbish', 'DD-Mon-YYYY')` does not
-- return null, it RAISES — so one malformed cell would fail the whole
-- migration. Only values matching the shape are converted; anything else keeps
-- the default and stays visible in `answers`.
-- ===========================================================================

alter table public.feedback
  add column if not exists entry_at      timestamptz not null default now(),
  add column if not exists imported_from text        not null default '';

comment on column public.feedback.entry_at is
  'When the feedback was taken. For a migrated row this is the export''s "Visit Entry Date"; for one recorded here it is when it was recorded. NOT created_at, which is when the ROW was written and reads as the upload date on every migrated feedback.';
comment on column public.feedback.imported_from is
  'The file this feedback was loaded from; EMPTY means it was recorded in this system. Lets a figure drawn from both report the split.';

create index if not exists feedback_entry_at_idx  on public.feedback (entry_at desc);
create index if not exists feedback_imported_idx  on public.feedback (imported_from);

-- ---------------------------------------------------------------------------
-- THE BACKFILL. Idempotent: it reads `answers`, which the importer wrote and
-- nothing else touches, so running it again lands on the same values.
-- ---------------------------------------------------------------------------
do $$
declare n_date int; n_visit int; n_from int;
begin
  if to_regclass('public.feedback') is null then return; end if;

  -- 1. WHERE IT CAME FROM. A row whose `answers` carries a heading only the
  --    export produces was loaded from it. "Visit Entry Date" is that heading
  --    and is also what the date comes from, so the two agree by construction.
  update public.feedback
     set imported_from = 'v2Feedback export'
   where imported_from = ''
     and answers ? 'Visit Entry Date';
  get diagnostics n_from = row_count;

  -- 2. THE FEEDBACK'S OWN DATE. Guarded on the SHAPE, because to_timestamp
  --    raises rather than returning null on anything it cannot read.
  update public.feedback
     set entry_at = to_timestamp(btrim(answers->>'Visit Entry Date'), 'DD-Mon-YYYY HH24:MI:SS')
   where answers->>'Visit Entry Date' ~ '^\s*\d{1,2}-[A-Za-z]{3}-\d{4}\s+\d{1,2}:\d{2}:\d{2}\s*$';
  get diagnostics n_date = row_count;

  -- ...and the date-only spelling, for a year that wrote it without a time.
  update public.feedback
     set entry_at = to_timestamp(btrim(answers->>'Visit Entry Date'), 'DD-Mon-YYYY')
   where answers->>'Visit Entry Date' ~ '^\s*\d{1,2}-[A-Za-z]{3}-\d{4}\s*$';

  -- 3. THE VISIT DATE, only where it is MISSING. The importer maps this one, so
  --    this catches rows loaded before that alias was added and touches nothing
  --    it already got right.
  update public.feedback
     set visit_at = to_timestamp(btrim(answers->>'Visit Date & Time'), 'DD Month YYYY')
   where visit_at is null
     and answers->>'Visit Date & Time' ~ '^\s*\d{1,2}\s+[A-Za-z]+\s+\d{4}\s*$';
  get diagnostics n_visit = row_count;

  raise notice '0190: % feedback row(s) marked as imported, % given their own date, % given a visit date',
    n_from, n_date, n_visit;
end $$;

-- ------------------------------------------------------------------------
-- 0208_cover_code_normalised.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ONE VOCABULARY FOR COVER: WGP, OGP, CMC, AMC — AND "WARRANTY" IS WGP.
--
-- Reported from use (the user, 2026-09-15), looking at Failures per cover:
-- "What is this Warranty? It has to be Normalized -- Warranty is WGP -- Where
-- ever this DAta is feeding - Fix that as well."
--
-- The chart read CMC 880, OGP 374, WGP 56, AMC 3 and **WARRANTY 1**. The last
-- one is not a fifth kind of cover; it is WGP spelled differently by whatever
-- loaded it. The application has said `['WGP','OGP','CMC','AMC']` since
-- `fieldcall.ts` was written, but nothing made the DATABASE agree, so a
-- register loaded from a file could carry any spelling its source used.
--
-- A SECOND SPELLING IS WORSE THAN A WRONG ONE HERE. Every count, share and
-- cross-tab on this dimension is a GROUP BY: two spellings of one cover do not
-- read as a small error, they split the total silently and the reader believes
-- both halves. One row today is the visible edge of it — the same load could
-- have carried a thousand.
--
-- NORMALISED AT THE DATABASE, NOT IN THE CHART. Rewriting the label where it is
-- drawn would leave the stored value wrong for every other reader — the DCCR
-- grid, the exports, the spare-approval rule that asks whether an item is AMC
-- or OGP — and the next screen would show the split again. So:
--
--   1. `public.cover_code(text)` is the ONE rule, in SQL.
--   2. A trigger applies it on every write to the five tables that store a
--      cover, so no importer, form or bulk load can reintroduce a synonym.
--   3. The existing rows are corrected once, here.
--
-- AN UNRECOGNISED VALUE IS LEFT EXACTLY AS IT IS, on purpose. Forcing anything
-- unknown into OGP would be a guess written into a quality record, and a wrong
-- cover on a failure is a wrong answer to "is this a manufacturing question or
-- a wear question". A spelling nobody anticipated stays visible as itself —
-- which is how this one was found.
-- ===========================================================================

create or replace function public.cover_code(v text)
returns text language sql immutable as $$
  select case
    when v is null or btrim(v) = '' then v
    else coalesce(
      (select m.code
         from (values
                -- WGP — inside the guarantee period. "Warranty" is the word
                -- people use; WGP is the code this system stores.
                ('wgp',                              'WGP'),
                ('warranty',                         'WGP'),
                ('underwarranty',                    'WGP'),
                ('inwarranty',                       'WGP'),
                ('withinwarranty',                   'WGP'),
                ('warrantyguaranteeperiod',          'WGP'),
                ('guaranteeperiod',                  'WGP'),
                -- OGP — out of it. Note these are matched WHOLE, so
                -- "outofwarranty" cannot be caught by the 'warranty' row
                -- above: the comparison is on the entire squashed string.
                ('ogp',                              'OGP'),
                ('outofwarranty',                    'OGP'),
                ('outofguaranteeperiod',             'OGP'),
                ('outofguarantee',                   'OGP'),
                ('outofcover',                       'OGP'),
                ('outofcontract',                    'OGP'),
                ('nocover',                          'OGP'),
                -- The two contracts.
                ('cmc',                              'CMC'),
                ('comprehensivemaintenancecontract', 'CMC'),
                ('undercmc',                         'CMC'),
                ('amc',                              'AMC'),
                ('annualmaintenancecontract',        'AMC'),
                ('underamc',                         'AMC')
              ) as m(src, code)
        where m.src = regexp_replace(lower(v), '[^a-z0-9]', '', 'g')),
      btrim(v))
  end
$$;
comment on function public.cover_code(text) is
  'The one rule for cover. WGP / OGP / CMC / AMC from any spelling that means '
  'one of them; anything else is returned trimmed and unchanged, because a '
  'guess written into a quality record is worse than a value that reads as odd.';

-- ---------------------------------------------------------------------------
-- The trigger, on every table that STORES a cover. `calls`, `pending_calls`
-- and `machine_cover` are views over these and follow without being touched.
-- ---------------------------------------------------------------------------
create or replace function public.cover_code_stamp()
returns trigger language plpgsql as $$
begin
  new.item_status := public.cover_code(new.item_status);
  return new;
end $$;

-- The two AppSheet cover exports spell the same thing in a column of their
-- own, `present_item_status` (0036 documents it as "OGP / WGP / CMC / AMC"),
-- and `machine_cover` reads it as a machine's cover alongside the rest. A
-- register left out of this list is exactly how one synonym survived.
create or replace function public.present_cover_code_stamp()
returns trigger language plpgsql as $$
begin
  new.present_item_status := public.cover_code(new.present_item_status);
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['field_calls','installation_calls','pm_calls','products','spare_requests']
  loop
    if to_regclass('public.' || t) is null then continue; end if;
    if (select c.relkind from pg_class c where c.oid = to_regclass('public.' || t)) <> 'r'
      then continue; end if;
    execute format('drop trigger if exists %I on public.%I', t || '_cover_code', t);
    execute format(
      'create trigger %I before insert or update of item_status on public.%I '
      'for each row execute function public.cover_code_stamp()', t || '_cover_code', t);
  end loop;

  -- ONLY A TABLE TAKES A ROW TRIGGER. `contract_details` carries the column
  -- and is a VIEW over `contract_items`, so it follows without being touched —
  -- and naming it here without this guard is an error that stops the migration
  -- dead, which is how the list gets quietly shortened instead of corrected.
  foreach t in array array['contract_items','contract_details']
  loop
    if to_regclass('public.' || t) is null then continue; end if;
    if (select c.relkind from pg_class c where c.oid = to_regclass('public.' || t)) <> 'r'
      then continue; end if;
    execute format('drop trigger if exists %I on public.%I', t || '_cover_code', t);
    execute format(
      'create trigger %I before insert or update of present_item_status on public.%I '
      'for each row execute function public.present_cover_code_stamp()', t || '_cover_code', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- The rows already stored. Only the ones the rule actually changes are
-- written: an update that touches every row would restamp `updated_at` across
-- five registers and bury the real change in the audit trail.
-- ---------------------------------------------------------------------------
do $$
declare t text; n int; total int := 0;
begin
  foreach t in array array['field_calls','installation_calls','pm_calls','products','spare_requests']
  loop
    if to_regclass('public.' || t) is null then continue; end if;
    execute format(
      'update public.%I set item_status = public.cover_code(item_status) '
      'where item_status is distinct from public.cover_code(item_status)', t);
    get diagnostics n = row_count;
    total := total + n;
    if n > 0 then raise notice '0208: %: % row(s) normalised', t, n; end if;
  end loop;

  foreach t in array array['contract_items','contract_details']
  loop
    if to_regclass('public.' || t) is null then continue; end if;
    if (select c.relkind from pg_class c where c.oid = to_regclass('public.' || t)) <> 'r'
      then continue; end if;
    execute format(
      'update public.%I set present_item_status = public.cover_code(present_item_status) '
      'where present_item_status is distinct from public.cover_code(present_item_status)', t);
    get diagnostics n = row_count;
    total := total + n;
    if n > 0 then raise notice '0208: %.present_item_status: % row(s) normalised', t, n; end if;
  end loop;
  raise notice '0208: % cover value(s) normalised in all', total;
end $$;

commit;
